import {icon,packArt,yardIllustration} from './art.js';
import {esc,kg,yardSVG,deckSVG,outline} from './visual.js';
let selectedWorker=null,workerMoveMode=false,placementDraft=null,placementSequence=0,placementTimer=null;
let app,api,notify,account,settings,state,view='HOME',selected=null,poll=null,segments=[],closed=false,editingYard=null,historyCursor=0,containerPage=0,componentTab='ALL',stockTab='REGISTER';
const options=(items,label='name')=>items.map(x=>`<option value="${esc(x.id)}">${esc(x[label])}</option>`).join('');
const select=(name,label,items)=>`<label>${label}<select name="${name}" required>${options(items)}</select></label>`;
const number=(name,label,value,min=0)=>`<label>${label}<input type="number" name="${name}" value="${value}" min="${min}" step="1" required></label>`;
const text=(name,label,value='')=>`<label>${label}<input name="${name}" value="${esc(value)}" required maxlength="250"></label>`;
const qty=(name='quantity',value=100)=>`${number(name,name==='workers'?'Workers':'Quantity',value)}<div class="quantity-buttons">${(name==='workers'?[-10,-5,-1,1,5,10]:[-100,-10,-5,-1,1,5,10,100]).map(n=>`<button type="button" class="secondary" data-adjust="${name}" data-delta="${n}">${n>0?'+':''}${n}</button>`).join('')}</div>`;
const name=id=>[...state.containers,...state.products,...state.yards,...state.sites,...state.trucks,...state.resources].find(x=>x.id===id)?.name??'Handling equipment';
const form=(id,title,content,button)=>`<details class="panel"><summary>${title}</summary><form id="${id}">${content}<div class="actions"><button>${button}</button></div></form></details>`;
async function command(action,data){const res=await fetch(`/api/commands/${action}`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(data)});const result=await res.json();if(!res.ok)throw new Error(result.error);return result;}
function bind(id,action,transform=x=>x){const node=document.getElementById(id);if(!node)return;node.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(node));node.querySelectorAll('input[type=number]').forEach(i=>data[i.name]=i.value===''?null:Number(i.value));const button=node.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await command(action,transform(data));notify('Saved.');await refresh(true);}catch(e){notify(e.message);}finally{if(button)button.disabled=false;}};}
function action(selector,handler){document.querySelectorAll(selector).forEach(el=>el.onclick=async()=>{try{await handler(el);await refresh(true);}catch(e){notify(e.message);}});}
export function stopOperations(){clearInterval(poll);poll=null;}
export async function openOperations(root,apiCall,notifyCall,userState,settingsCallback){if(account?.company.id!==userState.company.id||account?.user.id!==userState.user.id){view='HOME';selected=null;selectedWorker=null;containerPage=0;componentTab='ALL';stockTab='REGISTER';editingYard=null;segments=[];closed=false;}app=root;api=apiCall;notify=notifyCall;account=userState;settings=settingsCallback;stopOperations();await refresh(true);poll=setInterval(()=>{if(!document.querySelector('dialog[open]')&&!document.activeElement?.matches('input,select,textarea')&&!document.querySelector('details[open]'))refresh(false).catch(e=>{if(e.status===401)stopOperations();});},1000);}
async function refresh(force){const next=await api(`state?page=${containerPage}`);if(force||JSON.stringify(next)!==JSON.stringify(state)){state=next;render();}}
function render(){const oldWorkerPositions=new Map([...document.querySelectorAll('[data-worker],[data-forklift]')].map(el=>[el.dataset.worker??el.dataset.forklift,el.getAttribute('transform')]));const ops=account.permissions.includes('operations.manage');app.innerHTML=`<div class="workspace"><aside class="sidebar"><div class="workspace-tag">OPERATIONS WORKSPACE</div><div class="company-label">${esc(account.company.name)}</div><nav aria-label="Main navigation">${['HOME','YARD','STOCK','TRUCKS','SITES','REQUESTS'].map(v=>`<button class="nav-button ${v===view?'current':''}" data-view="${v}">${icon(v)} <span>${v}</span></button>`).join('')}<button class="nav-button" id="settings">${icon('SETTINGS')} <span>SETTINGS</span></button></nav><div class="sidebar-note">SIMULATION<br><small>Synthetic stock.<br>Server-controlled movements.</small></div></aside><section class="content"><div class="row"><div><div class="eyebrow">SCAFFOLD / ${view}</div><h1>${{HOME:'Your yard at a glance.',YARD:'A place for everything.',STOCK:'Every piece accounted for.',TRUCKS:'Ready for the next load.',SITES:'From yard to site.',REQUESTS:'The right material. On its way.'}[view]}</h1></div>${state.config&&ops?`<button class="secondary" id="pause">${state.config.paused?'Resume simulation':'Pause simulation'}</button>`:''}</div><div class="simulation-banner"><span class="status-dot"></span> SIMULATION / DEMONSTRATION <span>Not real lifting operations or certified load engineering.</span></div>${ops&&!state.yards.length?'<p class="notice">Start here: draw your yard → configure resources → add starting stock → open your yard.</p>':''}<div id="view">${view==='HOME'?homeView():view==='YARD'?yardView():view==='STOCK'?stockView():view==='TRUCKS'?truckView():view==='SITES'?siteView():requestView()}</div>${selected?detail():''}<section class="activity"><div class="row"><h2>Movement activity</h2><span class="muted">${state.tasks.length} active tasks</span></div>${state.tasks.length?state.tasks.map(t=>`<div class="task"><div><strong>${esc(name(t.container))}</strong> <span class="badge">${esc(t.type)}</span><p>${esc(t.state.replaceAll('_',' '))} · ${esc(name(t.from))} → ${esc(name(t.to))}${t.reason?`<br><span class="error-text">${esc(t.reason)}</span>`:''}</p></div><div>${t.state==='BLOCKED'?`<button class="secondary" data-retry="${t.id}">Retry</button>`:''}${!t.picked?`<button class="secondary" data-cancel="${t.id}">Cancel</button>`:''}</div></div>`).join(''):'<p class="muted">No movements waiting. Material stays where it is until you request a move.</p>'}</section><details class="panel"><summary>Notifications · ${state.notifications.length}</summary>${state.notifications.slice().reverse().map(n=>`<p><strong>${esc(n.title)}</strong><br>${esc(n.body)}</p>`).join('')||'<p>No notifications yet.</p>'}</details></section></div>`;
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;render();});document.querySelector('#settings').onclick=()=>{stopOperations();settings();};
  document.querySelector('#pause')?.addEventListener('click',async()=>{try{await command('pause',{paused:!state.config.paused});await refresh(true);}catch(e){notify(e.message);}});
  document.querySelectorAll('[data-retire]').forEach(b=>b.onclick=async()=>{const id=b.dataset.retire;if(!confirm('Remove '+(b.dataset.retireLabel||'this item')+' from the yard?'))return;try{await command('retire',{id});if(selectedWorker===id)selectedWorker=null;if(selected===id)selected=null;notify('Removed.');await refresh(true);}catch(e){notify(e.message);}});
  action('[data-quick]',e=>{const [kind,delta]=e.dataset.quick.split(':');return command('quickAdjust',{kind,delta:Number(delta),location:state.yards[0].id});});
  action('[data-retry]',e=>command('retry',{id:e.dataset.retry}));action('[data-cancel]',e=>command('cancel',{id:e.dataset.cancel}));
  document.querySelectorAll('[data-select]').forEach(el=>{const pick=()=>{selected=el.dataset.select;render();};el.onclick=pick;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick();}};});
  document.querySelectorAll('[data-adjust]').forEach(b=>b.onclick=()=>{const input=b.closest('form').querySelector(`[name="${b.dataset.adjust}"]`);input.value=Math.max(0,Number(input.value)+Number(b.dataset.delta));});
  document.querySelectorAll('[draggable=true]').forEach(el=>el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.select);e.dataTransfer.effectAllowed='move';el.classList.add('drag-ghost');el.ondragend=()=>el.classList.remove('drag-ghost');});
  document.querySelectorAll('[data-drop]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('drop-target');};el.ondragleave=()=>el.classList.remove('drop-target');el.ondrop=async e=>{e.preventDefault();el.classList.remove('drop-target');try{await command('queue',{container:e.dataTransfer.getData('text/plain'),destination:el.dataset.drop});notify('Move requested. A worker and machine will perform it.');await refresh(true);}catch(error){notify(error.message);}};});
  if(state.containerCount>100){document.querySelector('#view').insertAdjacentHTML('afterbegin',`<div class="actions"><button class="secondary" id="prev-page" ${containerPage===0?'disabled':''}>Previous 100 stillages / cages</button><span>Stillages / cages ${containerPage*100+1}?${Math.min((containerPage+1)*100,state.containerCount)} of ${state.containerCount}</span><button class="secondary" id="next-page" ${(containerPage+1)*100>=state.containerCount?'disabled':''}>Next 100 stillages / cages</button></div>`);document.querySelector('#prev-page').onclick=()=>{containerPage--;refresh(true);};document.querySelector('#next-page').onclick=()=>{containerPage++;refresh(true);};}
  if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('[data-worker],[data-forklift]').forEach(el=>{const before=oldWorkerPositions.get(el.dataset.worker??el.dataset.forklift),after=el.getAttribute('transform');if(before&&before!==after){const css=t=>t.replace(/translate\(([-.0-9]+) ([-.0-9]+)\)/,'translate($1px, $2px)');el.animate([{transform:css(before)},{transform:css(after)}],{duration:900,easing:'linear'});}});
  bindWorkers();
  bindViews();
}

function quickPanel(){const yard=state.yards[0];if(!yard||!account.permissions.includes('operations.manage'))return '';const rows=[['WORKER','Workers','worker',state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id).length],['FORKLIFT','Forklifts','forklift',state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id).length],['TRUCK','Trucks','truck',state.trucks.filter(t=>t.yard===yard.id).length],['STILLAGE','Stillages','stillage',state.containers.filter(c=>c.location===yard.id&&c.type==='STILLAGE').length]];return '<section class="panel"><div class="row"><h2>Quick adjustments</h2><span class="muted">'+esc(yard.name)+'</span></div><div class="quick-grid">'+rows.map(([kind,label,word,count])=>'<div class="quick-row"><span>'+label+'</span><button type="button" class="secondary" data-quick="'+kind+':-1" '+(count?'':'disabled')+'>&minus;1 '+word+'</button><strong>'+count+'</strong><button type="button" data-quick="'+kind+':1">+1 '+word+'</button></div>').join('')+'</div><p class="muted">Removing takes the most recently added one that is idle. Stillages must be empty; trucks must be unloaded and not planned for a trip. New stillages are placed in the next clear space.</p></section>';}
function homeView(){
 const workers=state.resources.filter(r=>r.type==='WORKER'),machines=state.resources.filter(r=>r.type!=='WORKER');
 const resourceRow=r=>{const task=state.tasks.find(t=>t.id===r.task);return '<tr><td><span class="resource-avatar">'+(r.type==='WORKER'?'W':'M')+'</span><strong>'+esc(r.name)+'</strong><small>'+esc(r.type.replaceAll('_',' '))+'</small></td><td>'+esc(name(r.location))+'</td><td><span class="badge '+(!r.task&&!r.walk&&!r.mountedOn&&!r.driver&&!r.claimedBy&&r.workerMode!=='HOLD'?'available':'busy')+'">'+(r.task?'Assigned':r.mountedOn?'Mounted':r.driver?'Occupied':r.claimedBy?'Reserved':r.walk?'Moving':r.workerMode==='HOLD'?'Holding':'Available')+'</span></td><td>'+(task?esc(task.type.replaceAll('_',' ')+' - '+task.state.replaceAll('_',' '))+'<small>'+esc(name(task.container))+' - '+esc(name(task.to))+'</small>':r.task?'Assigned to movement':r.mountedOn?'Driving '+esc(name(r.mountedOn)):r.driver?'Driver: '+esc(name(r.driver)):r.claimedBy?'Worker approaching':r.walk?'Walking to destination':r.workerMode==='HOLD'?'Holding position':'Ready for the next task')+'</td></tr>';};
 const table=list=>'<div class="table-scroll"><table><thead><tr><th>Name</th><th>Location</th><th>Availability</th><th>Current task</th></tr></thead><tbody>'+list.map(resourceRow).join('')+'</tbody></table></div>';
 return '<div class="metrics"><div><strong>'+workers.filter(r=>!r.task&&!r.walk&&!r.mountedOn&&r.workerMode!=='HOLD').length+' / '+workers.length+'</strong><span>Workers available</span></div><div><strong>'+machines.filter(r=>!r.task&&!r.driver&&!r.claimedBy).length+' / '+machines.length+'</strong><span>Machines available</span></div><div><strong>'+state.trucks.filter(t=>t.status==='AT_YARD').length+'</strong><span>Trucks at yard</span></div><div><strong>'+(state.availability?.serviceablePieces??0).toLocaleString()+'</strong><span>Serviceable, unreserved pieces</span></div></div>'+quickPanel()+'<section class="panel home-intro"><div class="hero-copy"><div class="eyebrow">Daily operations</div><h2>A clear view.<br>A yard that works.</h2><p>Live worker assignments across your yards and sites.</p></div><button data-view="YARD">Open yard plan &rarr;</button>'+yardIllustration()+'</section><section class="panel"><div class="row"><h2>Workers</h2><span class="badge">'+workers.length+' configured</span></div>'+(workers.length?table(workers):'<p>No workers configured. Open the yard to add your team.</p>')+'</section><section class="panel"><h2>Equipment</h2>'+(machines.length?table(machines):'<p>No handling equipment configured.</p>')+'</section><section class="panel"><h2>Stock & storage</h2><p><strong>'+(state.availability?.stillages??0)+'</strong> stillages / racks / bundles - <strong>'+(state.availability?.cages??0)+'</strong> small-parts cages</p><p>'+state.stockTotal.toLocaleString()+' physical pieces - '+state.reservedTotal.toLocaleString()+' reserved</p><button class="secondary" data-view="STOCK">View available stock</button></section>';
}
function parkingForm(yard){if(!yard)return '';const p=yard.parking;const metres=(key,label,value)=>'<label>'+label+'<input type="number" name="'+key+'" value="'+value+'" min="'+(key==='clearance'?0:1)+'" max="'+(key==='vehicleWidth'?5:key==='clearance'?10:30)+'" step="0.01" required></label>';return form('parking','Truck parking apron - dimensions', '<p>Separate apron beside the storage boundary. Confirm the available land and enter the overall vehicle size, including cab. Clearance applies on all four sides.</p>'+(!p?'<p class="notice">Preview uses your 6 m deck plus an assumed 3 m cab: 9 x 2.1 m truck with 0.5 m clearance. Replace these with your measurements.</p>':'')+select('side','Side of yard',[{id:p?.side??'RIGHT',name:p?.side==='LEFT'?'Left':'Right'},{id:p?.side==='LEFT'?'RIGHT':'LEFT',name:p?.side==='LEFT'?'Right':'Left'}])+metres('vehicleLength','Overall truck length (m)',(p?.vehicleLength??9000)/1000)+metres('vehicleWidth','Overall truck width (m)',(p?.vehicleWidth??2100)/1000)+metres('clearance','Clearance on each side (m)',(p?.clearance??500)/1000),'Save parking dimensions');
}

function truckRemoveButton(t){if(!account.permissions.includes('operations.manage'))return '';const busy=t.status==='IN_TRANSIT'||state.containers.some(c=>c.location===t.id)||state.tasks.some(x=>x.to===t.id||x.from===t.id)||(state.loadLists??[]).some(l=>l.truck===t.id&&!l.cancelled&&!l.delivery);return `<button type="button" class="secondary" data-retire="${t.id}" data-retire-label="truck ${esc(t.name)}" ${busy?'disabled':''}>Remove truck</button>`;}
function emptyState(type,title,body){return `<section class="panel empty-state">${icon(type)}<h2>${title}</h2><p>${body}</p></section>`;}
function containerCards(location){return `<div class="container-list">${state.containers.filter(c=>!location||c.location===location).map(c=>`<button class="container-card" data-select="${c.id}" draggable="true">${packArt(c.type)}<strong>${esc(c.name)}</strong><small>${esc(c.type)} · ${state.balances.filter(l=>l.container===c.id).reduce((s,l)=>s+l.quantity,0)} pieces</small><small class="condition-label ${c.condition==='SERVICEABLE'?'good':'attention'}">${esc(c.condition)}</small></button>`).join('')||'<p class="muted">No stillages or cages here yet.</p>'}</div>`;}
function yardView(){const yard=state.yards[0];const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard?.id).length;return `<div class="metrics"><div><strong>${state.containers.filter(c=>c.location===yard?.id).length}</strong><span>Stillages & cages in yard</span></div><div><strong>${workers}</strong><span>Yard workers</span></div><div><strong>${state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard?.id).length}</strong><span>Forklifts</span></div><div><strong>${state.sites.filter(s=>s.status==='ACTIVE').length}</strong><span>Active sites</span></div></div>${yard?`<section class="panel scene"><div class="row"><h2><span class="section-kicker">LIVE YARD PLAN</span>${esc(yard.name)}</h2><span>${(yard.area/1e6).toFixed(1)} m² · 1 m grid</span></div>${yardSVG(yard,state.containers,state.tasks,selected,state.trucks,state.resources,selectedWorker)}<div class="scene-caption"><div class="map-legend"><span><i class="legend-dot stillage"></i>Stillages</span><span><i class="legend-dot cage"></i>Small-parts cages</span><span><i class="legend-dot loading"></i>Loading zone</span></div><span>Left-click worker to select &middot; Right-click ground to move</span></div></section>${workerPanel(yard)}${yardListsPanel(l=>['OPEN','PARTIAL','RESERVED','LOADED'].includes(l.status),false)}${containerCards(yard.id)}<div class="drop-zones">${state.trucks.filter(t=>t.at===yard.id&&t.status==='AT_YARD').map(t=>`<div class="drop-zone" data-drop="${t.id}"><strong>▰ ${esc(t.name)}</strong><span>Drop a stillage or cage to request loading</span>${truckRemoveButton(t)}</div>`).join('')}</div><div class="actions"><button class="secondary" id="edit-yard">Edit yard perimeter</button></div>`:''}${!yard||editingYard?builder():''}${account.permissions.includes('operations.manage')?parkingForm(yard)+resourceForm(yard)+containerForm(yard):''}`;}
function builder(){const preview=outline(segments,closed);return `<section class="panel" id="builder"><h2>${editingYard?'Edit yard':'Draw your yard'}</h2><p>Each line starts where the last one ends. Enter its actual length in metres.</p><div class="builder-grid"><div><form id="segment"><fieldset><legend>Direction</legend><div class="directions">${[['NW','↖'],['UP','↑'],['NE','↗'],['LEFT','←'],['RIGHT','→'],['SW','↙'],['DOWN','↓'],['SE','↘']].map(([d,s])=>`<label><input type="radio" name="direction" value="${d}" ${d==='RIGHT'?'checked':''}>${s} ${d}</label>`).join('')}</div></fieldset><label>Line length (m)<input type="number" name="metres" min="0.001" max="1000" step="0.001" value="20" required></label><button>Add segment</button></form><ol>${segments.map((s,i)=>`<li><select aria-label="Segment ${i+1} direction" data-segment-dir="${i}">${['RIGHT','LEFT','UP','DOWN','NE','SE','SW','NW'].map(d=>`<option ${s.direction===d?'selected':''}>${d}</option>`).join('')}</select><input aria-label="Segment ${i+1} length in metres" type="number" min="0.001" step="0.001" data-segment-length="${i}" value="${s.length/1000}"> m</li>`).join('')}</ol><div class="actions"><button class="secondary" id="undo-segment">Undo last</button><button class="secondary" id="reset-segments">Reset</button><button class="secondary" id="close-yard">${closed?'Perimeter closed ✓':'Preview and close perimeter'}</button></div><p class="muted">Closing adds the displayed last-to-first boundary explicitly. Endpoints within 1 mm are treated as closed.</p><form id="save-yard">${text('name','Yard name',editingYard?.name??'Main yard')}${number('height','Maximum storage height (mm)',editingYard?.height??10000,1)}<fieldset><legend>Loading zone &amp; gate</legend><p class="muted">Positions are the top-left corner in metres from the yard origin. Loading needs a clear 2 × 1.5 m footprint inside the boundary; truck loading routes start and end here.</p><div class="form-grid">${[['loadingX','Loading zone X (m)',editingYard?.loading?.x],['loadingY','Loading zone Y (m)',editingYard?.loading?.y],['gateX','Gate X (m)',editingYard?.gate?.x],['gateY','Gate Y (m)',editingYard?.gate?.y]].map(([k,l,v])=>`<label>${l}<input type="number" name="${k}" value="${(v??1000)/1000}" step="0.01" required></label>`).join('')}</div></fieldset><button ${closed?'':'disabled'}>Save yard</button></form></div><div>${yardSVG({name:'Boundary preview',points:preview.points})}<p>${closed?'Closing edge confirmed.':'The last-to-first line is a closing preview only.'}</p></div></div></section>`;}
function resourceForm(location){if(!location)return '';return form('resources','Configure workers & equipment · DEMO ONLY',select('location','Location',[...state.yards,...state.sites.filter(s=>s.status==='ACTIVE')])+qty('workers',5)+number('machines','Forklifts (yard) / cranes (site)',1)+number('capacity','Machine capacity (grams)',1500000,1)+number('stepMs','Pickup / placement time (milliseconds)',700,100)+number('speed','Travel speed (mm per second)',4000,1)+number('craneWorkers','Workers required per crane task',1,1),'Save resources');}
function containerForm(location){if(!location)return '';return form('container','Add a stillage or small-parts cage',text('name','Stillage / cage label',`S-${String(state.containers.length+1).padStart(3,'0')}`)+select('location','Storage location',[...state.yards,...state.sites.filter(s=>s.status==='ACTIVE')])+select('type','Storage type',[{id:'STILLAGE',name:'Open stillage - scaffold tubes & ledgers'},{id:'CAGE',name:'Mesh cage - fittings & small items'},{id:'RACK',name:'Storage rack'},{id:'BUNDLE',name:'Strapped bundle'}])+`<div class="form-grid">${number('length','Frame length (mm)',2000,1)}${number('width','Frame width (mm)',1000,1)}${number('height','Frame height (mm)',1000,1)}${number('envelopeLength','Loaded length (mm)',2000,1)}${number('envelopeWidth','Loaded width (mm)',1000,1)}${number('tare','Frame tare (g) — DEMO',50000)}${number('x','X position (mm)',4000,-1000000)}${number('y','Y position (mm)',4000,-1000000)}</div><p class="muted">These suggested dimensions and weights are synthetic simulation values, not manufacturer ratings.</p>`,'Register stillage / cage');}
function componentsPanel(){const tabs=[{id:'ALL',name:'All components'},...account.systems.filter(s=>s.enabled)];const active=tabs.some(s=>s.id===componentTab)?componentTab:'ALL';const products=state.products.filter(p=>active==='ALL'||p.system===active);return `<section class="panel"><div class="row"><h2>Components</h2><span class="badge">${products.length} of ${state.products.length}</span></div><div class="subtabs" role="tablist">${tabs.map(s=>`<button type="button" class="secondary ${s.id===active?'current':''}" data-component-tab="${s.id}" role="tab" aria-selected="${s.id===active}">${esc(s.name)}</button>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>Name</th><th>System</th><th>Category</th><th>Manufacturer / reference</th><th>Unit weight</th><th>Pack qty</th><th>Verification</th></tr></thead><tbody>${products.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(account.systems.find(s=>s.id===p.system)?.name??p.system)}</td><td>${esc(p.category)}</td><td>${esc(p.manufacturer)} · ${esc(p.reference)}</td><td>${p.unitWeight!==null?kg(p.unitWeight):'Unknown'}</td><td>${p.packQuantity??'—'}</td><td>${esc(p.verification)}</td></tr>`).join('')||'<tr><td colspan="7">No components in this system yet.</td></tr>'}</tbody></table></div></section>`;}
const when=iso=>{try{return new Date(iso).toLocaleString();}catch{return esc(iso);}};
const storageContainers=()=>state.containers.filter(c=>state.yards.some(y=>y.id===c.location)||state.sites.some(y=>y.id===c.location));
const enabledProducts=()=>state.products.filter(p=>account.systems.some(s=>s.id===p.system&&s.enabled));
function stockTabs(){const tabs=[['REGISTER','Materials register'],['ADDED','Added stock'],['REMOVED','Removed stock'],['CONTAINERS','Stillages & cages'],['COMPONENTS','Components']];return '<div class="subtabs" role="tablist">'+tabs.map(([id,label])=>'<button type="button" class="secondary '+(id===stockTab?'current':'')+'" data-stock-tab="'+id+'" role="tab" aria-selected="'+(id===stockTab)+'">'+label+'</button>').join('')+'</div>';}
function registerPanel(){const rows=state.register??[];return '<section class="panel"><div class="row"><h2>Materials register</h2><a class="button-link" href="/api/export?kind=register">Export register CSV</a></div><p>Total stock the company owns right now, per product, across the yard, sites and trucks. This is the original list of stock plus everything added, minus everything removed.</p><div class="table-scroll"><table><thead><tr><th>Product</th><th>System</th><th>In yard</th><th>At sites</th><th>On trucks</th><th>Total</th><th>Reserved</th><th>Available</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong>'+esc(r.name)+'</strong><small>'+esc(r.category??'')+'</small></td><td>'+esc(account.systems.find(s=>s.id===r.system)?.name??r.system??'')+'</td><td>'+r.yard+'</td><td>'+r.site+'</td><td>'+r.truck+'</td><td><strong>'+r.quantity+'</strong></td><td>'+r.reserved+'</td><td>'+r.available+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="8">No stock has been recorded yet. Record your original stock below.</td></tr>')+'</tbody></table></div></section>'+(account.permissions.includes('stock.adjust')?form('opening','Record original stock (opening balance)',select('container','Stillage / cage',storageContainers())+select('product','Product',enabledProducts())+qty()+text('reason','Reason','Original stock on hand'),'Record original stock'):'');}
function stockLogTable(rows,empty){return '<div class="table-scroll"><table><thead><tr><th>When</th><th>Product</th><th>Quantity</th><th>Stillage / cage</th><th>Location</th><th>Reason</th></tr></thead><tbody>'+rows.map(l=>'<tr><td>'+when(l.created_at)+'<small>'+esc(l.event.replaceAll('_',' '))+'</small></td><td>'+esc(name(l.product_id))+'</td><td><strong>'+l.quantity+'</strong></td><td>'+esc(name(l.container_id))+'</td><td>'+esc(name(l.destination??l.source))+'</td><td>'+esc(l.reason)+'</td></tr>').join('')+(rows.length?'':'<tr><td colspan="6">'+empty+'</td></tr>')+'</tbody></table></div>';}
function additionsPanel(){return '<section class="panel"><div class="row"><h2>Added stock</h2><a class="button-link" href="/api/export?kind=additions">Export additions CSV</a></div><p>Every purchase and original-stock receipt, newest first.</p>'+stockLogTable(state.additions??[],'Nothing has been added yet.')+'</section>'+(account.permissions.includes('stock.adjust')?form('purchase','Record a purchase',select('container','Receive into stillage / cage',storageContainers())+select('product','Product',enabledProducts())+qty()+'<label>Supplier (optional)<input name="supplier" maxlength="250"></label>'+text('reason','Reason / invoice reference','Purchased stock'),'Add purchased stock'):'');}
function removalsPanel(){return '<section class="panel"><div class="row"><h2>Removed stock</h2><a class="button-link" href="/api/export?kind=removals">Export removals CSV</a></div><p>Stock sold, scrapped or otherwise taken out of the company, newest first. Reserved, in-transit and counted stock cannot be removed.</p>'+stockLogTable(state.removals??[],'Nothing has been removed yet.')+'</section>'+(account.permissions.includes('stock.adjust')?form('remove-stock','Record a sale / removal',select('container','Remove from stillage / cage',storageContainers().filter(c=>state.balances.some(l=>l.container===c.id)))+select('product','Product',enabledProducts())+qty('quantity',10)+text('reason','Reason / sale reference','Sold to customer'),'Remove stock'):'');}
const listBadge=s=>({OPEN:'busy',PARTIAL:'busy',RESERVED:'available',LOADED:'available',IN_TRANSIT:'available',AT_SITE:'available',DELIVERED:'available',CANCELLED:''}[s]??'');
function loadListCard(l,controls){const ops=account.permissions.includes('operations.manage');const truckSelect=state.trucks.filter(t=>t.status==='AT_YARD'&&(!t.destination||t.destination===l.site));return '<section class="panel load-list" data-load-list="'+l.id+'"><div class="row"><h2>'+esc(l.name)+'</h2><span class="badge '+listBadge(l.status)+'">'+esc(l.status.replaceAll('_',' '))+(l.short&&!['OPEN','CANCELLED'].includes(l.status)?' · '+l.short+' short':'')+'</span></div><p>To <strong>'+esc(name(l.site))+'</strong>'+(l.truckName?' · truck <strong>'+esc(l.truckName)+'</strong>':'')+' · '+l.requested+' pieces requested · '+(l.delivery?l.lines.reduce((s,x)=>s+(x.sent??0),0)+' sent':l.loaded+' on truck')+' · '+l.delivered+' at site'+(l.departedAt?' · departed '+when(l.departedAt):'')+(l.notes?' · '+esc(l.notes):'')+'</p><div class="table-scroll"><table><thead><tr><th>Product</th><th>Requested</th><th>Reserved</th><th>'+(l.delivery?'Sent':'On truck')+'</th><th>At site</th><th>Line</th></tr></thead><tbody>'+l.lines.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.quantity+'</td><td>'+x.reserved+'</td><td>'+(l.delivery?(x.sent??0)+(x.sent?'':' <small>not sent</small>'):x.loaded)+'</td><td>'+x.delivered+'</td><td><span class="badge '+(x.status==='DELIVERED'?'available':x.status==='REQUESTED'?'busy':'')+'">'+esc(x.status.replaceAll('_',' '))+'</span>'+(x.lastReason&&x.status==='REQUESTED'?'<br><span class="error-text">'+esc(x.lastReason)+'</span>':'')+'</td></tr>').join('')+'</tbody></table></div>'+(controls&&!l.cancelled?'<div class="actions">'+(ops&&l.lines.some(x=>x.status==='REQUESTED')?'<form data-allocate-list="'+l.id+'" class="inline-form">'+(truckSelect.length?'<label>Loading truck<select name="truck" required>'+options(truckSelect)+'</select></label><button>Reserve packs &amp; load truck</button>':'<span class="muted">No truck at the yard for this site.</span>')+'</form>':'')+(!['DELIVERED'].includes(l.status)?'<button type="button" class="secondary" data-cancel-list="'+l.id+'">Cancel remaining lines</button>':'')+'</div>':'')+(l.cancelled&&l.cancelReason?'<p class="muted">Cancelled: '+esc(l.cancelReason)+'</p>':'')+'</section>';}
function loadListForm(){const products=enabledProducts(),sites=state.sites.filter(s=>s.status==='ACTIVE');if(!sites.length||!products.length)return '';const row=i=>'<div class="load-line"><label>Product<select name="product'+i+'"><option value="">— none —</option>'+options(products)+'</select></label><label>Quantity<input type="number" name="quantity'+i+'" min="0" step="1" value="0"></label></div>';return '<details class="panel" id="load-list-panel"><summary>Create a yard list (load list for one truck)</summary><form id="load-list"><p>List everything the yardsman must put on the truck for this site. The same list travels with the truck as the delivery docket. Each product once; leave unused lines at 0.</p>'+text('name','Yard list name','Yard list '+new Date().toISOString().slice(0,10))+select('site','Destination site',sites)+'<label>Notes<input name="notes" maxlength="250" value="Demonstration delivery"></label><div id="load-lines">'+[0,1,2,3].map(row).join('')+'</div><div class="actions"><button type="button" class="secondary" id="add-load-line">Add another line</button><button>Create yard list</button></div></form></details>';}
function yardListsPanel(filter,controls){const lists=(state.loadLists??[]).filter(filter);if(!lists.length)return '';return lists.map(l=>loadListCard(l,controls)).join('');}
function manifestPanel(delivery,title){const lists=delivery?.manifest??[];if(!lists.length)return '';return '<section class="panel"><div class="row"><h2>'+title+'</h2><span class="badge">'+esc(delivery.status)+'</span></div><p>'+esc(name(delivery.from))+' → '+esc(name(delivery.to))+' · '+delivery.containers.length+' stillages / cages · '+when(delivery.createdAt)+'</p>'+lists.map(l=>loadListCard(l,false)).join('')+'</section>';}
function stockView(){const total=state.stockTotal,reserved=state.reservedTotal;return `<div class="metrics"><div><strong>${total.toLocaleString()}</strong><span>Physical pieces in your scope</span></div><div><strong>${reserved}</strong><span>Reserved · included in physical stock</span></div><div><strong>${total-reserved}</strong><span>Unreserved pieces</span></div></div>${stockTabs()}${stockTab==='REGISTER'?registerPanel():stockTab==='ADDED'?additionsPanel():stockTab==='REMOVED'?removalsPanel():stockTab==='COMPONENTS'?componentsPanel():`<section class="panel"><div class="row"><h2>Stock by stillage & cage</h2><a class="button-link" href="/api/export?kind=stock">Export stock CSV</a></div><label>Search product or stillage / cage<input id="stock-search" type="search" placeholder="Ledger, S-001…"></label><div class="table-scroll"><table aria-label="Stock by stillage & cage"><thead><tr><th>Product</th><th>Stillage / cage / location</th><th>Physical</th><th>Reserved</th><th>Available</th><th>Condition</th></tr></thead><tbody>${state.balances.map(l=>`<tr data-stock-row><td>${esc(name(l.product_id))}</td><td><button class="text-button" data-select="${l.container}">${esc(name(l.container))}</button><small>${esc(name(l.location))}</small></td><td>${l.quantity}</td><td>${l.reserved}</td><td>${l.condition==='SERVICEABLE'?l.quantity-l.reserved:0}</td><td>${esc(l.condition)}</td></tr>`).join('')||'<tr><td colspan="6">No stock has been received.</td></tr>'}</tbody></table></div></section>${account.permissions.includes('operations.manage')?form('count','Start a stocktake',select('scope','Count scope',[...state.yards,...state.sites,...state.containers]),'Start count and lock scope'):''}${state.counts.map(c=>`<section class="panel"><h2>Stocktake · ${esc(c.name)} <span class="badge">${c.state}</span></h2>${c.state==='OPEN'?`<form data-count="${c.id}">${c.lines.map((l,i)=>number(`line${i}`,`${name(l.product_id)} in ${name(l.container)} · expected ${l.expected}`,l.observed??l.expected)).join('')}${text('reason','Reason for any variance',c.reason??'')}<button>Save observed counts</button></form><div class="actions">${c.lines.every(l=>l.observed!==null)?`<button data-approve="${c.id}">Approve correction</button>`:''}<button class="secondary" data-cancel-count="${c.id}">Cancel count</button></div>`:`<p>${esc(c.reason??'Count cancelled')}</p><p>${c.lines.map(l=>`${esc(name(l.product_id))}: ${l.expected} expected → ${l.observed??'—'} counted`).join('<br>')}</p>`}</section>`).join('')}<details class="panel"><summary>Movement and adjustment history</summary><div class="actions"><button id="load-history">Load next 100 records</button><a href="/api/export?kind=history">Export history CSV (up to 10,000)</a></div><div id="history"></div></details>`}`;}
function truckView(){return `${!state.trucks.length?emptyState('TRUCKS','Your fleet starts here.','Add a truck to plan its load and follow deliveries.'):''}${state.trucks.map(t=>`<section class="panel" data-drop="${t.id}"><div class="row"><h2>▰ ${esc(t.name)}</h2><span class="badge">${esc(t.status.replaceAll('_',' '))}</span></div>${deckSVG(t,state.containers)}<div class="metrics compact"><div><strong>${kg(t.loadedWeight)}</strong><span>Loaded</span></div><div><strong>${kg(t.reservedWeight)}</strong><span>Reserved</span></div><div><strong>${kg(t.loadedWeight===null||t.reservedWeight===null?null:t.payload-t.loadedWeight-t.reservedWeight)}</strong><span>Remaining / ${kg(t.payload)}</span></div><div><strong>${(100*t.deckArea/(t.length*t.width)).toFixed(1)}%</strong><span>Ground deck occupied</span></div></div><p>At: ${esc(name(t.at))} · Destination: ${t.destination?esc(name(t.destination)):'Not assigned'}</p><div class="actions">${truckRemoveButton(t)}</div>${manifestPanel(state.deliveries.find(d=>d.id===t.delivery),'Delivery docket on board')}${t.status!=='IN_TRANSIT'?`<form data-dispatch="${t.id}">${select('destination','Travel destination',[...state.sites.filter(s=>s.status==='ACTIVE'),...state.yards].filter(s=>s.id!==t.at))}<div class="actions"><button>Dispatch truck</button><button type="button" class="secondary" data-unload="${t.id}">Unload at current location</button></div></form>`:'<p>Truck travelling. Its cargo remains truck stock.</p>'}${containerCards(t.id)}</section>`).join('')}${account.permissions.includes('operations.manage')?form('truck','Add a truck',text('name','Truck name',`T-${String(state.trucks.length+1).padStart(2,'0')}`)+select('yard','Home yard',state.yards)+number('length','Deck length (mm)',6000,1)+number('width','Deck width (mm)',2100,1)+number('payload','Payload (g)',12500000,1),'Add truck'):''}`;}
function siteView(){return `${!state.sites.length?emptyState('SITES','Ready for your next site.','Create a site to track deliveries, returns and stock.'):''}${state.sites.map(s=>`<section class="panel"><div class="row"><h2>⚑ ${esc(s.name)}</h2><span class="badge">${s.status}</span></div><p>${esc(s.address)}</p>${yardSVG(s,state.containers,state.tasks,selected)}${state.deliveries.filter(d=>d.to===s.id&&d.manifest?.length).slice(-5).reverse().map(d=>manifestPanel(d,'Delivery docket')).join('')}${containerCards(s.id)}<div class="drop-zones">${state.trucks.filter(t=>t.at===s.id&&t.status==='AT_SITE').map(t=>`<div class="drop-zone" data-drop="${t.id}"><strong>▰ ${esc(t.name)}</strong><span>At this site · drop a stillage or cage to load it for return</span>${truckRemoveButton(t)}</div>`).join('')}</div>${account.permissions.includes('operations.manage')&&s.status!=='ARCHIVED'?`<button class="secondary" data-archive="${s.id}">Archive empty site</button>`:''}</section>`).join('')}${account.permissions.includes('operations.manage')?form('site','Create a site',text('name','Site name')+text('address','Address / location')+`<label>Assigned supervisor<select name="supervisor"><option value="">Not assigned</option>${options(account.users)}</select></label>`,'Create site'):''}`;}
function requestView(){return `${!state.requests.length&&!(state.loadLists??[]).length?emptyState('REQUESTS','Every delivery starts with a yard list.','List the materials for a site below; the yard reserves exact packs, loads the truck and the list travels as the delivery docket.'):''}${loadListForm()}${yardListsPanel(l=>!l.cancelled&&l.status!=='DELIVERED',true)}${yardListsPanel(l=>l.cancelled||l.status==='DELIVERED',true)}${form('request','Quick single-line request',select('site','Destination site',state.sites.filter(s=>s.status==='ACTIVE'))+select('product','Exact product variant',state.products.filter(p=>account.systems.some(s=>s.id===p.system&&s.enabled)))+qty()+text('notes','Delivery notes','Demonstration delivery'),'Send to yard')}${state.requests.filter(r=>!r.loadList).map(r=>`<section class="panel"><div class="row"><h2>${esc(name(r.site))}</h2><span class="badge">${esc(r.status)}</span></div><p><strong>${r.quantity} × ${esc(name(r.product))}</strong></p><p>Allocated: ${r.allocated} · Placed at site: ${r.delivered} · Exact quantity only.</p>${r.status==='REQUESTED'&&account.permissions.includes('operations.manage')?`<form data-allocate="${r.id}">${select('truck','Loading truck',state.trucks.filter(t=>t.status==='AT_YARD'))}<button>Plan packs & load truck</button></form>`:''}</section>`).join('')}`;}
function detail(){const c=state.containers.find(c=>c.id===selected);if(!c)return '';const lines=state.balances.filter(l=>l.container===c.id);return `<section class="panel selected-detail"><div class="row"><h2>${esc(c.name)} · ${esc(c.type)}</h2>${account.permissions.includes('operations.manage')?`<button class="secondary" data-retire="${c.id}" data-retire-label="${esc(c.name)}" ${lines.length||!(state.yards.some(y=>y.id===c.location)||state.sites.some(s=>s.id===c.location))?'disabled':''}>Remove stillage / cage</button>`:''}<button class="secondary" id="close-detail">Close</button></div><p>${esc(name(c.location))} · ${esc(c.condition)} · ${c.envelopeLength} × ${c.envelopeWidth} × ${c.height} mm · tare ${kg(c.tare)}</p>${lines.map(l=>`<p><strong>${l.quantity} × ${esc(name(l.product_id))}</strong> · ${kg(state.products.find(p=>p.id===l.product_id)?.unitWeight)} each · ${l.reserved} reserved</p>`).join('')||'<p>Empty stillage / cage</p>'}<p class="muted">Source yard: ${c.sourceYard?esc(name(c.sourceYard)):'—'} · Last placed: ${esc(c.placedAt??'Not moved yet')}</p><form id="move">${select('destination','Move to',[...state.yards,...state.trucks,...state.sites.filter(s=>s.status==='ACTIVE')])}<details><summary>Exact placement (optional)</summary><div class="form-grid">${number('x','X (mm)',0,-1000000)}${number('y','Y (mm)',0,-1000000)}<label>Rotation<select name="rotation"><option>0</option><option>90</option></select></label><label>Supporting stillage / cage<select name="support"><option value="">Ground level</option>${options(state.containers.filter(o=>o.id!==c.id))}</select></label></div><label class="inline-check"><input name="exact" type="checkbox"> Use these coordinates</label></details><button>Confirm move request</button></form>${account.permissions.includes('operations.manage')?form('condition','Change condition',select('condition','Condition',['SERVICEABLE','DAMAGED','QUARANTINED'].map(id=>({id,name:id})))+text('reason','Condition reason'),'Record condition')+form('container-settings','Configure stillage / cage weight & loaded envelope',number('tare','Tare (g)',c.tare??'')+number('envelopeLength','Loaded length (mm)',c.envelopeLength,1)+number('envelopeWidth','Loaded width (mm)',c.envelopeWidth,1)+text('reason','Configuration reason','Company configured'),'Save frame settings'):''}</section>`;}
function bindViews(){
  bind('parking','parking',d=>({id:state.yards[0].id,side:d.side,vehicleLength:Math.round(d.vehicleLength*1000),vehicleWidth:Math.round(d.vehicleWidth*1000),clearance:Math.round(d.clearance*1000)}));
  document.querySelector('#container [name=type]')?.addEventListener('change',e=>{const f=e.target.form,cage=e.target.value==='CAGE';for(const key of ['length','envelopeLength'])f.elements.namedItem(key).value=cage?1200:2000;for(const key of ['width','envelopeWidth'])f.elements.namedItem(key).value=1000;f.elements.namedItem('name').value=(cage?'C-':'S-')+String(state.containers.length+1).padStart(3,'0');});
  bind('condition','condition',d=>({...d,id:selected}));bind('container-settings','containerSettings',d=>({...d,id:selected}));bind('resources','resources');bind('container','container');bind('opening','opening');bind('truck','truck');bind('site','site');bind('request','request');bind('count','count');bind('move','queue',d=>({container:selected,destination:d.destination,...(d.exact?{position:{x:d.x,y:d.y,rotation:Number(d.rotation),support:d.support||null}}:{})}));
  document.querySelector('#close-detail')?.addEventListener('click',()=>{selected=null;render();});
  document.querySelector('#edit-yard')?.addEventListener('click',()=>{editingYard=state.yards[0];segments=structuredClone(editingYard.segments);closed=true;render();});
  const segment=document.querySelector('#segment');if(segment)segment.onsubmit=e=>{e.preventDefault();const data=new FormData(segment);segments.push({direction:data.get('direction'),length:Math.round(Number(data.get('metres'))*1000)});closed=false;render();};
  document.querySelectorAll('[data-segment-dir]').forEach(el=>el.onchange=()=>{segments[Number(el.dataset.segmentDir)].direction=el.value;closed=false;render();});document.querySelectorAll('[data-segment-length]').forEach(el=>el.onchange=()=>{segments[Number(el.dataset.segmentLength)].length=Math.round(Number(el.value)*1000);closed=false;render();});
  document.querySelector('#undo-segment')?.addEventListener('click',()=>{segments.pop();closed=false;render();});document.querySelector('#reset-segments')?.addEventListener('click',()=>{if(confirm('Clear all unsaved yard segments?')){segments=[];closed=false;render();}});document.querySelector('#close-yard')?.addEventListener('click',()=>{closed=true;render();});
  bind('save-yard','yard',({loadingX,loadingY,gateX,gateY,...d})=>({...d,segments,closed,loading:{x:Math.round(loadingX*1000),y:Math.round(loadingY*1000)},gate:{x:Math.round(gateX*1000),y:Math.round(gateY*1000)},...(editingYard?{id:editingYard.id}: {})}));
  document.querySelector('#stock-search')?.addEventListener('input',e=>{document.querySelectorAll('[data-stock-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));});
  document.querySelectorAll('[data-component-tab]').forEach(b=>b.onclick=()=>{componentTab=b.dataset.componentTab;render();});
  document.querySelectorAll('[data-stock-tab]').forEach(b=>b.onclick=()=>{stockTab=b.dataset.stockTab;render();});bind('purchase','purchase');bind('remove-stock','removeStock');
  document.querySelector('#add-load-line')?.addEventListener('click',()=>{const box=document.querySelector('#load-lines'),i=box.children.length;box.insertAdjacentHTML('beforeend','<div class="load-line"><label>Product<select name="product'+i+'"><option value="">— none —</option>'+options(enabledProducts())+'</select></label><label>Quantity<input type="number" name="quantity'+i+'" min="0" step="1" value="0"></label></div>');});
  const loadForm=document.querySelector('#load-list');if(loadForm)loadForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(loadForm),lines=[];for(let i=0;fd.has('product'+i);i++){const product=fd.get('product'+i),quantity=Number(fd.get('quantity'+i));if(product&&quantity>0)lines.push({product,quantity});}if(!lines.length){notify('Add at least one product line with a quantity.');return;}try{await command('createLoadList',{name:fd.get('name'),site:fd.get('site'),notes:fd.get('notes'),lines});notify('Yard list created. Reserve packs to start loading.');await refresh(true);}catch(error){notify(error.message);}};
  document.querySelectorAll('[data-allocate-list]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{const result=await command('allocateLoadList',{id:form.dataset.allocateList,truck:new FormData(form).get('truck')});const short=result.outcome.filter(o=>o.status==='SHORT');notify(short.length?`${result.outcome.length-short.length} line(s) reserved; ${short.length} short: ${short.map(o=>o.reason).join(' ')}`:'Every line reserved. Loading tasks queued.');await refresh(true);}catch(error){notify(error.message);}});
  action('[data-cancel-list]',e=>command('cancelLoadList',{id:e.dataset.cancelList,reason:'Remaining lines cancelled by user'}));
  document.querySelectorAll('[data-allocate]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await command('allocate',{id:form.dataset.allocate,truck:new FormData(form).get('truck')});await refresh(true);notify('Exact pack plan reserved. Loading tasks queued.');}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-dispatch]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await command('dispatch',{id:form.dataset.dispatch,destination:new FormData(form).get('destination')});await refresh(true);}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-count]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),count=state.counts.find(c=>c.id===form.dataset.count);try{await command('observe',{id:count.id,observed:count.lines.map((l,i)=>Number(fd.get(`line${i}`))),reason:fd.get('reason')});await refresh(true);}catch(error){notify(error.message);}});
  action('[data-cancel-request]',e=>command('cancelRequest',{id:e.dataset.cancelRequest,reason:'User cancelled unstarted remainder'}));
  action('[data-approve]',e=>command('approveCount',{id:e.dataset.approve}));action('[data-cancel-count]',e=>command('cancelCount',{id:e.dataset.cancelCount}));action('[data-unload]',e=>command('unload',{id:e.dataset.unload}));action('[data-archive]',e=>command('archive',{id:e.dataset.archive}));
  document.querySelector('#load-history')?.addEventListener('click',async()=>{try{const rows=await api(`history?after=${historyCursor}&limit=100`);historyCursor=rows.at(-1)?.sequence??historyCursor;document.querySelector('#history').innerHTML=rows.map(l=>`<p>#${l.sequence} ${esc(l.event)} · ${l.quantity} · ${esc(l.reason)}<br><time>${esc(l.created_at)}</time></p>`).join('')||'<p>No more records.</p>';}catch(e){notify(e.message);}});
}

export function catalogueSettings(){return `<section class="panel"><h2>Catalogue & provenance</h2><p>All suggested demo data is synthetic. No manufacturer documents were imported.</p><button id="seed-demo" ${state?.products.length?'disabled':''}>Add synthetic demo catalogue</button></section>${state?form('override-product','Configure a product’s operational values',select('product','Product',state.products)+number('unitWeight','Unit weight (g)',5000)+number('packQuantity','Operating full-pack quantity',100,1)+text('reason','Reason','Company-configured DEMO values'),'Save company override'):''}`;}
export function bindCatalogue(){document.querySelector('#seed-demo')?.addEventListener('click',async()=>{try{await command('seed',{});state=await api('state');notify('Synthetic catalogue added. Return to the yard to add stillages, cages and stock.');settings();}catch(e){notify(e.message);}});bind('override-product','override');}

function workerPanel(yard){const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id),w=workers.find(r=>r.id===selectedWorker);return '<section class="worker-command-panel"><div class="worker-roster">'+workers.map(r=>'<button class="secondary '+(r.id===selectedWorker?'worker-active':'')+'" data-worker-pick="'+esc(r.id)+'">'+esc(r.name)+'</button>').join('')+'</div>'+forkliftRoster(yard)+(w?'<button class="worker-close secondary" data-worker-clear aria-label="Deselect worker">&times;</button><div class="worker-orders"><div class="worker-portrait" aria-hidden="true">'+'<svg viewBox="0 0 64 72" aria-hidden="true"><path d="M10 68v-18q22-15 44 0v18" fill="#e8dc55"/><circle cx="32" cy="30" r="15" fill="#dfaf80"/><path d="M14 26q0-23 18-23t18 23z" fill="#f1cd48"/><path d="M10 27h44M23 47v21M42 47v21" stroke="#fff0b9" stroke-width="5"/></svg></div><div><div class="eyebrow">SELECTED WORKER</div><h2>'+esc(w.name)+'</h2><p>'+(w.task?'Assigned to material handling':w.mountedOn?forkliftStatus(w):w.mountTarget?'Walking to '+esc(name(w.mountTarget)):w.walk?'Walking to destination':w.workerMode==='HOLD'?'Holding position':'Ready for automatic work')+'</p>'+(w.workerReason?'<p class="error-text">'+esc(w.workerReason)+'</p>':'')+'</div></div>'+(account.permissions.includes('operations.manage')?'<div class="worker-buttons"><button data-worker-order="MOVE" '+(w.task?'disabled':'')+'>'+(w.mountedOn?'Drive':'Move')+'</button><button class="secondary" data-worker-order="STOP" '+(w.task?'disabled':'')+'>Stop</button><button class="secondary" data-worker-order="HOLD" '+(w.task?'disabled':'')+'>Hold position</button><button class="secondary" data-worker-order="AUTO" '+(w.task||w.mountedOn?'disabled':'')+'>Return to work</button>'+mountControls(w,yard)+'<button class="secondary" data-retire="'+esc(w.id)+'" data-retire-label="worker '+esc(w.name)+'" '+(w.task||w.walk||w.mountedOn||w.mountTarget?'disabled':'')+'>Remove worker</button></div>':'')+(workerMoveMode==='PLACE'?placementPanel():'')+'<p class="worker-help">'+(workerMoveMode==='PLACE'?'Move the pointer to preview. Click to pin, adjust or rotate, then Confirm placement. R rotates; arrow keys nudge.':workerMoveMode?'Click open ground to set the destination.':w.mountedOn?'Right-click ground to drive. Select a stillage, then Pick up. Place load lets you choose its new position.':'Left-click selects. Right-click open ground moves. Hold keeps the worker out of automatic jobs; Return to work makes them available again.')+'</p>':'<h2>Your yard crew</h2><p>'+(workers.length?'Select a worker on the plan or above to give orders.':'Configure workers below to add your crew to the yard.')+'</p>')+'</section>';}
function forkliftRoster(yard){if(!account.permissions.includes('operations.manage'))return '';const machines=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id);if(!machines.length)return '';return '<div class="forklift-roster">'+machines.map(m=>{const busy=m.task||m.driver||m.claimedBy||m.cargo||m.drive;return '<span><strong>'+esc(m.name)+'</strong> · '+(m.driver?'Driver: '+esc(name(m.driver)):m.task?'On a task':m.claimedBy?'Worker approaching':'Available')+'</span><button type="button" class="secondary" data-retire="'+esc(m.id)+'" data-retire-label="'+esc(m.name)+'" '+(busy?'disabled':'')+'>Remove forklift</button>';}).join('')+'</div>';}
function bindWorkers(){
 document.querySelector('[data-worker-clear]')?.addEventListener('click',()=>{selectedWorker=null;workerMoveMode=false;render();});
 const pick=id=>{if(id!==selectedWorker)workerMoveMode=false;selectedWorker=id;render();};
 document.querySelectorAll('[data-worker]').forEach(el=>{el.onclick=e=>{e.stopPropagation();pick(el.dataset.worker);};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(el.dataset.worker);}};});
 document.querySelectorAll('[data-worker-pick]').forEach(el=>el.onclick=()=>pick(el.dataset.workerPick));
 document.querySelectorAll('[data-worker-order]').forEach(el=>el.onclick=async()=>{const order=el.dataset.workerOrder;if(order==='MOUNT'){try{await command('workerCommand',{id:selectedWorker,order,forklift:document.querySelector('#mount-forklift').value});await refresh(true);}catch(e){notify(e.message);}return;}if(order==='PICKUP'){try{await command('workerCommand',{id:selectedWorker,order,container:selected});await refresh(true);}catch(e){notify(e.message);}return;}if(order==='PLACE'){beginPlacement();return;}if(order==='MOVE'){workerMoveMode='MOVE';render();notify('Click open ground to move, or right-click a destination.');return;}try{await command('workerCommand',{id:selectedWorker,order});workerMoveMode=false;await refresh(true);}catch(e){notify(e.message);}});
 document.querySelectorAll('[data-forklift]').forEach(el=>{const choose=()=>{const m=state.resources.find(r=>r.id===el.dataset.forklift);if(m.driver){pick(m.driver);}else{notify(m.claimedBy?'A worker is walking to this forklift.':'Select a worker, then use Mount Forklift.');}};el.onclick=e=>{e.stopPropagation();choose();};el.onkeydown=e=>{if(e.key==='Enter'){choose();}};});
 const svg=document.querySelector('.scene .yard-svg');if(!svg||view!=='YARD')return;
 const move=async e=>{if(!selectedWorker||!account.permissions.includes('operations.manage'))return;e.preventDefault();const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const at=point.matrixTransform(svg.getScreenCTM().inverse());try{await command('workerCommand',{id:selectedWorker,order:workerMoveMode==='PLACE'?'PLACE':'MOVE',x:Math.round(at.x-(workerMoveMode==='PLACE'?0:state.resources.find(r=>r.id===selectedWorker)?.mountedOn?1100:250)),y:Math.round(at.y-(workerMoveMode==='PLACE'?0:state.resources.find(r=>r.id===selectedWorker)?.mountedOn?600:250))});workerMoveMode=false;await refresh(true);}catch(error){notify(error.message);}};
 if(workerMoveMode==='PLACE'){bindPlacement(svg);return;}
 svg.oncontextmenu=move;svg.onclick=e=>{if(workerMoveMode&&!e.target.closest('[data-worker],[data-select]'))move(e);};
}

function mountControls(w,yard){if(w.mountedOn){const m=state.resources.find(r=>r.id===w.mountedOn),c=state.containers.find(r=>r.id===selected);return '<button data-worker-order="PICKUP" '+(m?.cargo||m?.drive||!c||c.location!==yard.id?'disabled':'')+'>Pick up'+(c?' '+esc(c.name):' selected stillage')+'</button><button data-worker-order="PLACE" '+(!m?.cargo||m?.drive?'disabled':'')+'>Place load</button><button class="secondary" data-worker-order="DISMOUNT" '+(w.task||m?.cargo||m?.drive?'disabled':'')+'>Dismount Forklift</button>';}const machines=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id&&!r.task&&!r.driver&&!r.claimedBy&&Number.isFinite(r.x));return '<label class="mount-choice">Forklift<select id="mount-forklift" '+(!machines.length?'disabled':'')+'>'+ (machines.length?options(machines):'<option>No free forklift</option>')+'</select></label><button data-worker-order="MOUNT" '+(w.task||w.mountTarget||!machines.length?'disabled':'')+'>Mount Forklift</button>';}

function forkliftStatus(w){const m=state.resources.find(r=>r.id===w.mountedOn);return esc(name(w.mountedOn))+' - '+(m?.drive?(m.drive.order==='PICKUP'?'Approaching stillage':m.drive.order==='PLACE'?'Moving to placement':'Driving'):m?.cargo?'Carrying '+esc(m.cargoPreview?.name??name(m.cargo)):'Ready to drive')+(m?.manualReason?'<br><span class="error-text">'+esc(m.manualReason)+'</span>':'');}

function beginPlacement(){const w=state.resources.find(r=>r.id===selectedWorker),m=state.resources.find(r=>r.id===w?.mountedOn);if(!m?.cargoPreview)return;workerMoveMode='PLACE';placementDraft={worker:selectedWorker,cargo:m.cargo,x:Math.round(m.x+2200),y:Math.round(m.y),rotation:m.cargoPreview.rotation??0,snap:100,pinned:false,valid:false,message:'Choose a position on the yard plan.'};render();checkPlacement();}
function placementPanel(){if(!placementDraft)return '';const d=placementDraft;return '<form id="placement-form"><div class="row"><h3>Precise placement</h3><span id="placement-size"></span></div><div class="placement-fields"><label>X (mm)<input name="px" type="number" step="1" min="-1000000" max="1000000" value="'+d.x+'" required></label><label>Y (mm)<input name="py" type="number" step="1" min="-1000000" max="1000000" value="'+d.y+'" required></label><label>Grid snap<select name="snap">'+[1,10,50,100,500,1000].map(n=>'<option value="'+n+'" '+(d.snap===n?'selected':'')+'>'+n+' mm</option>').join('')+'</select></label></div><div class="placement-tools"><button type="button" class="secondary" id="placement-rotate">Rotate 90 deg</button><strong id="placement-angle">'+d.rotation+' deg</strong><button type="button" class="secondary" data-nudge="-1,0" aria-label="Nudge left">Left</button><button type="button" class="secondary" data-nudge="1,0" aria-label="Nudge right">Right</button><button type="button" class="secondary" data-nudge="0,-1" aria-label="Nudge up">Up</button><button type="button" class="secondary" data-nudge="0,1" aria-label="Nudge down">Down</button></div><p id="placement-validation" role="status">'+esc(d.message)+'</p><div class="placement-tools"><button id="placement-confirm" disabled>Confirm placement</button><button type="button" class="secondary" id="placement-reposition">Choose another spot</button><button type="button" class="secondary" id="placement-cancel">Cancel</button></div><p class="muted">X/Y locate the top-left corner of the loaded footprint. Typed coordinates are exact; snapping applies to map clicks. Dashed outline shows forklift access.</p></form>';}
function placementLoad(){const w=state.resources.find(r=>r.id===placementDraft?.worker),m=state.resources.find(r=>r.id===w?.mountedOn);return m?.cargo===placementDraft?.cargo?m.cargoPreview:null;}
function paintPlacement(){const d=placementDraft,svg=document.querySelector('.scene .yard-svg'),c=placementLoad();if(!d||workerMoveMode!=='PLACE'||!svg||!c)return;const width=d.rotation===90?c.envelopeWidth:c.envelopeLength,height=d.rotation===90?c.envelopeLength:c.envelopeWidth,color=d.valid?'#36852e':d.pending?'#ba8730':'#bd4636';svg.querySelector('#placement-ghost')?.remove();const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='placement-ghost';g.setAttribute('pointer-events','none');if(Number.isFinite(d.x)&&Number.isFinite(d.y))g.innerHTML='<rect x="'+(d.x-2200)+'" y="'+d.y+'" width="2200" height="1200" fill="none" stroke="'+color+'" stroke-width="45" stroke-dasharray="110 70"/>'+(d.plan?.rotationClearance?'<rect x="'+d.plan.rotationClearance.x+'" y="'+d.plan.rotationClearance.y+'" width="'+d.plan.rotationClearance.w+'" height="'+d.plan.rotationClearance.h+'" fill="none" stroke="#bb872e" stroke-width="30" stroke-dasharray="70 90"/>':'')+'<rect x="'+d.x+'" y="'+d.y+'" width="'+width+'" height="'+height+'" fill="'+color+'" fill-opacity=".3" stroke="'+color+'" stroke-width="60"/><path d="M '+(d.x-170)+' '+d.y+' H '+(d.x+170)+' M '+d.x+' '+(d.y-170)+' V '+(d.y+170)+'" stroke="'+color+'" stroke-width="35"/><text x="'+d.x+'" y="'+(d.y-260)+'" font-size="230" fill="'+color+'" stroke="#f8ffeb" stroke-width="12" paint-order="stroke">'+width+' x '+height+' mm / '+d.rotation+' deg</text>';svg.append(g);const status=document.querySelector('#placement-validation');if(status){status.textContent=d.message;status.className=d.valid?'placement-valid':d.pending?'':'error-text';}const confirm=document.querySelector('#placement-confirm');if(confirm)confirm.disabled=!d.valid||d.pending;document.querySelector('#placement-angle')?.replaceChildren(document.createTextNode(d.rotation+' deg'));document.querySelector('#placement-size')?.replaceChildren(document.createTextNode(width+' x '+height+' mm'));}
async function checkPlacement(){clearTimeout(placementTimer);const d=placementDraft,seq=++placementSequence;if(!d||workerMoveMode!=='PLACE')return;d.valid=false;d.pending=true;d.plan=null;d.message='Checking footprint, access and rotation clearance...';paintPlacement();try{const plan=await api('placement-preview',{id:d.worker,container:d.cargo,x:d.x,y:d.y,rotation:d.rotation});if(seq!==placementSequence||d!==placementDraft||workerMoveMode!=='PLACE')return;d.plan=plan;d.valid=true;d.message='Position and route clear. Confirm to place.';}catch(e){if(seq!==placementSequence||d!==placementDraft)return;d.message=e.message;}d.pending=false;paintPlacement();}
function editPlacement(x,y){const d=placementDraft;if(!d)return;placementSequence++;d.x=x;d.y=y;d.valid=false;d.pending=true;d.plan=null;d.message='Checking position...';const f=document.querySelector('#placement-form');if(f){f.elements.namedItem('px').value=Number.isFinite(x)?x:'';f.elements.namedItem('py').value=Number.isFinite(y)?y:'';}paintPlacement();clearTimeout(placementTimer);placementTimer=setTimeout(checkPlacement,180);}
function bindPlacement(svg){const d=placementDraft,f=document.querySelector('#placement-form');if(!d||!f)return;paintPlacement();const rotate=()=>{d.rotation=d.rotation===0?90:0;editPlacement(d.x,d.y);};const nudge=(x,y)=>{d.pinned=true;editPlacement(d.x+x*d.snap,d.y+y*d.snap);};const pick=(e,pin)=>{const point=svg.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const at=point.matrixTransform(svg.getScreenCTM().inverse());if(pin)d.pinned=true;editPlacement(Math.round(at.x/d.snap)*d.snap,Math.round(at.y/d.snap)*d.snap);};svg.onpointermove=e=>{if(!d.pinned&&e.pointerType!=='touch')pick(e,false);};svg.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();pick(e,true);},true);svg.oncontextmenu=e=>{e.preventDefault();pick(e,true);};for(const key of ['px','py'])f.elements.namedItem(key).oninput=()=>{d.pinned=true;editPlacement(f.elements.namedItem('px').valueAsNumber,f.elements.namedItem('py').valueAsNumber);};f.elements.namedItem('snap').onchange=e=>{d.snap=Number(e.target.value);};document.querySelector('#placement-rotate').onclick=rotate;document.querySelectorAll('[data-nudge]').forEach(b=>b.onclick=()=>nudge(...b.dataset.nudge.split(',').map(Number)));document.querySelector('#placement-reposition').onclick=()=>{d.pinned=false;notify('Move over the yard and click to pin a new position.');};const cancel=()=>{placementSequence++;clearTimeout(placementTimer);placementDraft=null;workerMoveMode=false;render();};document.querySelector('#placement-cancel').onclick=cancel;app.onkeydown=e=>{if(workerMoveMode!=='PLACE'||e.target.matches('input,select,textarea'))return;if(e.key.toLowerCase()==='r'){e.preventDefault();rotate();}const keys={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(keys[e.key]){e.preventDefault();nudge(...keys[e.key]);}if(e.key==='Escape')cancel();};f.onsubmit=async e=>{e.preventDefault();if(!d.valid||d.pending)return;document.querySelector('#placement-confirm').disabled=true;try{await command('workerCommand',{id:d.worker,container:d.cargo,order:'PLACE',x:d.x,y:d.y,rotation:d.rotation});placementDraft=null;workerMoveMode=false;placementSequence++;await refresh(true);notify('Exact placement confirmed. Forklift moving.');}catch(error){d.valid=false;d.message=error.message;paintPlacement();}};}
